* { box-sizing: border-box; }
body { margin:0; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  background:#f7f7f5; color:#2b2b2b; line-height:1.5; }
.wrap { max-width:720px; margin:0 auto; padding:28px 20px 80px; }
h1 { font-size:20px; font-weight:600; margin:0 0 2px; }
.sub { color:#9a9a92; font-size:13px; margin:0 0 6px; }
.variant { display:inline-block; font-size:12px; font-weight:600; color:#4a6b57; background:#e9f0ec; padding:3px 10px; border-radius:999px; margin-bottom:22px; }
.list { display:flex; flex-direction:column; gap:12px; }
.item { position:relative; background:#fff; border:1px solid #e7e7e2; border-radius:14px; padding:14px 16px;
  box-shadow:0 1px 2px rgba(0,0,0,0.03); display:flex; gap:14px; }
.thumb { width:82px; min-width:82px; height:60px; border-radius:8px; display:flex; align-items:center;
  justify-content:center; color:#fff; font-size:12px; font-weight:600; text-align:center; }
.body { flex:1; min-width:0; }
.titleline { display:flex; align-items:center; gap:8px; }
.favicon { width:18px; height:18px; min-width:18px; border-radius:5px; display:flex; align-items:center;
  justify-content:center; color:#fff; font-size:10px; font-weight:700; }
.title { font-size:15.5px; font-weight:600; margin:0; }
.desc { font-size:13.5px; color:#55554e; margin:6px 0 8px; }
.chips { display:flex; flex-wrap:wrap; gap:6px; align-items:center; }
.chip { background:#eef0ee; color:#4a4a44; font-size:12px; padding:3px 10px; border-radius:999px; }
.badge { font-size:11px; padding:2px 9px; border-radius:999px; background:#f2ede0; color:#8a7a4a; font-weight:600; }
.url { font-size:11.5px; color:#9a9a92; word-break:break-all; margin:8px 0 0; }
.edit { position:absolute; right:14px; bottom:12px; font-size:12px; color:#8a8a82; cursor:pointer; text-decoration:underline; }
.openbtn { display:inline-flex; align-items:center; gap:4px; margin-top:10px; font-size:12.5px; font-weight:600;
  color:#4a6b57; background:#e9f0ec; border:none; border-radius:999px; padding:5px 12px; cursor:pointer; }
.link { color:#3a5a47; cursor:pointer; text-decoration:none; }
.link:hover { text-decoration:underline; }
.card-clickable { cursor:pointer; }
.card-clickable:hover { border-color:#cdd8d1; box-shadow:0 2px 10px rgba(74,107,87,0.10); }
.toast { position:fixed; left:50%; bottom:26px; transform:translateX(-50%); background:#2b2b2b; color:#fff;
  padding:10px 16px; border-radius:10px; font-size:13px; opacity:0; transition:.2s; pointer-events:none; max-width:90%; }
.toast.show { opacity:1; }

