  const q=query.trim(); if(!q) return true; const h=haystack(b);
  if(ast&&!astError){ try{ return evalAst(ast,b,h); }catch(e){} }
  return q.toLowerCase().split(/\s+/).filter(Boolean).every(x=>h.includes(x));
}
