  let out=esc(text);
  hlTerms.forEach(t=>{ if(!t) return; const re=new RegExp("("+t.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")+")","ig"); out=out.replace(re,'<span class="hl">$1</span>'); });
  return out;
}

