// --- query language: words, "phrases", #labels, AND/OR/NOT, parentheses ---
function tokenize(q){
  const toks=[]; let i=0; const stop=' \t()"';
  while(i<q.length){
    const c=q[i];
    if(c===' '||c==='\t'){ i++; continue; }
    if(c==='('){ toks.push({t:'('}); i++; continue; }
    if(c===')'){ toks.push({t:')'}); i++; continue; }
    if(c==='"'){ let j=i+1,s=""; while(j<q.length&&q[j]!=='"'){ s+=q[j]; j++; } i=(j<q.length)?j+1:j; toks.push({t:'TERM',kind:'phrase',v:s}); continue; }
    if(c==='#'){ let j=i+1,s=""; if(q[j]==='"'){ j++; while(j<q.length&&q[j]!=='"'){ s+=q[j]; j++; } i=(j<q.length)?j+1:j; } else { while(j<q.length&&!stop.includes(q[j])){ s+=q[j]; j++; } i=j; } toks.push({t:'TERM',kind:'label',v:s}); continue; }
    let j=i,s=""; while(j<q.length&&!stop.includes(q[j])){ s+=q[j]; j++; } i=j;
    if(s==='AND') toks.push({t:'AND'});
    else if(s==='OR') toks.push({t:'OR'});
    else if(s==='NOT') toks.push({t:'NOT'});
    else toks.push({t:'TERM',kind:'word',v:s});
  }
  return toks;
}
function parse(toks){
  let p=0; const peek=()=>toks[p], eat=()=>toks[p++];
