  function pAnd(){ let l=pNot(); while(peek()&&(peek().t==='AND'||peek().t==='TERM'||peek().t==='('||peek().t==='NOT')){ if(peek().t==='AND') eat(); l={op:'and',l,r:pNot()}; } return l; }
  function pNot(){ if(peek()&&peek().t==='NOT'){ eat(); return {op:'not',c:pNot()}; } return pPrim(); }
  function pPrim(){ const tk=peek(); if(!tk) throw new Error("end"); if(tk.t==='('){ eat(); const e=pOr(); if(peek()&&peek().t===')') eat(); else throw new Error(")"); return e; } if(tk.t==='TERM'){ eat(); return {op:'term',kind:tk.kind,v:tk.v}; } throw new Error("tok"); }
