* { box-sizing: border-box; }
body { margin:0; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  background:#f7f7f5; color:#2b2b2b; line-height:1.5; }
.wrap { max-width:720px; margin:0 auto; padding:28px 20px 80px; }
h1 { font-size:20px; font-weight:600; margin:0 0 2px; }
.sub { color:#9a9a92; font-size:13px; margin:0 0 6px; }
.variant { display:inline-block; font-size:12px; font-weight:600; color:#4a6b57; background:#e9f0ec; padding:3px 10px; border-radius:999px; margin-bottom:18px; }

.filter { display:inline-flex; background:#eceae4; border-radius:10px; padding:3px; gap:2px; margin-bottom:18px; }
.filter button { border:none; background:transparent; font-size:13px; color:#6a6a63; padding:6px 14px; border-radius:8px; cursor:pointer; }
.filter button.active { background:#fff; color:#2b2b2b; font-weight:600; box-shadow:0 1px 2px rgba(0,0,0,0.06); }
.filter .n { color:#a7a7a0; font-weight:400; margin-left:4px; font-size:12px; }

.list { display:flex; flex-direction:column; gap:12px; }
.item { position:relative; background:#fff; border:1px solid #e7e7e2; border-radius:14px; padding:14px 16px;
  box-shadow:0 1px 2px rgba(0,0,0,0.03); display:flex; gap:14px; align-items:flex-start; }
.item.done { opacity:0.72; }
.thumb { width:82px; min-width:82px; height:60px; border-radius:8px; display:flex; align-items:center;
  justify-content:center; color:#fff; font-size:12px; font-weight:600; text-align:center; }
.body { flex:1; min-width:0; }
.titleline { display:flex; align-items:center; gap:8px; }
.favicon { width:18px; height:18px; min-width:18px; border-radius:5px; display:flex; align-items:center;
  justify-content:center; color:#fff; font-size:10px; font-weight:700; }
.title { font-size:15.5px; font-weight:600; margin:0; }
.desc { font-size:13.5px; color:#55554e; margin:6px 0 8px; }
.chips { display:flex; flex-wrap:wrap; gap:6px; align-items:center; }
.chip { background:#eef0ee; color:#4a4a44; font-size:12px; padding:3px 10px; border-radius:999px; }
.badge { font-size:11px; padding:2px 9px; border-radius:999px; background:#f2ede0; color:#8a7a4a; font-weight:600; }
.badge.read { background:#e9f0ec; color:#3f6b53; }

/* Version A: check control */
.check { width:24px; min-width:24px; height:24px; border-radius:50%; border:2px solid #cdd4cf; cursor:pointer;
  display:flex; align-items:center; justify-content:center; color:#fff; font-size:13px; margin-top:2px; }
.check.on { background:#4a6b57; border-color:#4a6b57; }

/* Version B: badge toggle */
.badge.toggle { cursor:pointer; }
.badge.toggle:hover { filter:brightness(0.97); }

/* Version C: explicit action */
.statusbtn { margin-top:10px; font-size:12.5px; font-weight:600; color:#4a6b57; background:#e9f0ec;
  border:none; border-radius:999px; padding:5px 12px; cursor:pointer; }

.empty { text-align:center; color:#9a9a92; padding:44px 20px; }
.empty .big { font-size:15px; color:#6a6a63; margin-bottom:4px; }
.toast { position:fixed; left:50%; bottom:26px; transform:translateX(-50%); background:#2b2b2b; color:#fff;
  padding:10px 16px; border-radius:10px; font-size:13px; opacity:0; transition:.2s; pointer-events:none; }
.toast.show { opacity:1; }

