const archivedToggleEl = document.getElementById("archivedToggle");
const archivedBanner = document.getElementById("archivedBanner");
const bulkbarEl = document.getElementById("bulkbar");
function archivedCount(){ return bookmarks.filter(b=>b.archived).length; }

function selectedList(){ return bookmarks.filter(b=>selected.has(b.id)); }

function renderBulk(filtered){
  const n = selected.size;
  if(n===0){ bulkbarEl.classList.remove("show"); bulkbarEl.innerHTML=""; bulkMode="actions"; return; }
  bulkbarEl.classList.add("show");
  const visN = filtered.length;
  const allVisSelected = visN>0 && filtered.every(b=>selected.has(b.id));
  const selAll = allVisSelected
    ? `<button class="selall" data-selnone="1">Clear selection</button>`
    : `<button class="selall" data-selall="1">Select all ${visN} in this view</button>`;
  let actions;
  if(bulkMode==="addlabel")
    actions = `<input id="bulkLabelInput" placeholder="Label to add…" /><button class="act" data-doadd="1">Add to ${n}</button><button class="link" data-cancel="1">Cancel</button>`;
  else if(bulkMode==="removelabel")
    actions = `<input id="bulkLabelInput" placeholder="Label to remove…" /><button class="act" data-dorem="1">Remove from ${n}</button><button class="link" data-cancel="1">Cancel</button>`;
  else if(bulkMode==="confirmdelete")
    actions = `<span>Delete ${n} permanently? This can't be undone.</span><button class="act danger" data-dodelete="1">Delete ${n}</button><button class="link" data-cancel="1">Cancel</button>`;
  else if(archivedView)
    actions = `<button class="act" data-brestore="1">Restore</button><button class="act danger" data-confirmdelete="1">Delete</button>`;
  else
    actions = `<button class="act" data-mread="1">Mark read</button><button class="act" data-munread="1">Mark unread</button><button class="act" data-addlabel="1">Add label</button><button class="act" data-removelabel="1">Remove label</button><button class="act" data-archive="1">Archive</button><button class="act danger" data-confirmdelete="1">Delete</button>`;
  bulkbarEl.innerHTML = `<span class="count">${n} selected</span>${selAll}<span class="spacer"></span>${actions}<button class="link" data-clear="1">Done</button>`;

  const on=(sel,fn)=>{ const el=bulkbarEl.querySelector(sel); if(el) el.onclick=fn; };
  on("[data-selall]", ()=>{ filtered.forEach(b=>selected.add(b.id)); render(); });
  on("[data-selnone]", ()=>{ selected.clear(); render(); });
  on("[data-clear]", ()=>{ selected.clear(); render(); });
  on("[data-cancel]", ()=>{ bulkMode="actions"; render(); });
  on("[data-mread]", ()=>{ selectedList().forEach(b=>b.readLater=false); finishBulk(); });
  on("[data-munread]", ()=>{ selectedList().forEach(b=>b.readLater=true); finishBulk(); });
  on("[data-archive]", ()=>{ selectedList().forEach(b=>b.archived=true); finishBulk(); });
  on("[data-brestore]", ()=>{ selectedList().forEach(b=>b.archived=false); finishBulk(); });
  on("[data-addlabel]", ()=>{ bulkMode="addlabel"; render(); const i=document.getElementById("bulkLabelInput"); if(i) i.focus(); });
  on("[data-removelabel]", ()=>{ bulkMode="removelabel"; render(); const i=document.getElementById("bulkLabelInput"); if(i) i.focus(); });
  on("[data-doadd]", ()=>{ const v=document.getElementById("bulkLabelInput").value.trim(); if(v) selectedList().forEach(b=>{ b.tags=b.tags||[]; if(!b.tags.some(t=>t.toLowerCase()===v.toLowerCase())) b.tags.push(v); }); bulkMode="actions"; finishBulk(); });
  on("[data-dorem]", ()=>{ const v=document.getElementById("bulkLabelInput").value.trim().toLowerCase(); if(v) selectedList().forEach(b=>{ b.tags=(b.tags||[]).filter(t=>t.toLowerCase()!==v); }); bulkMode="actions"; finishBulk(); });
  on("[data-confirmdelete]", ()=>{ bulkMode="confirmdelete"; render(); });
  on("[data-dodelete]", ()=>{ bookmarks=bookmarks.filter(b=>!selected.has(b.id)); bulkMode="actions"; finishBulk(); });
}
function finishBulk(){ selected.clear(); save(); render(); }

