    listEl.innerHTML = '<div class="empty"><div class="big">Nothing saved yet.</div><div>Paste a link above to keep your first one.</div></div>';
    return;
  }

  const base = bookmarks.filter(b=> archivedView ? b.archived : !b.archived);
  const searchSet = base.filter(matches);

  if(archivedView){
    filterEl.innerHTML="";
    archivedBanner.className="archived-banner show";
    archivedBanner.innerHTML=`<span>Archived — hidden from your main list and search. Restore any to bring it back.</span>`;
  } else {
    renderFilter(searchSet);
    archivedBanner.classList.remove("show");
  }
  renderSort();

  let filtered = archivedView ? searchSet
    : searchSet.filter(b=> filter==="all" ? true : filter==="toread" ? b.readLater : !b.readLater);
  filtered = filtered.slice().sort(sortCmp);
  lastVisibleIds = filtered.map(b=>b.id);

  countEl.textContent = query.trim() ? (filtered.length===1 ? "1 match" : filtered.length+" matches") : "";
  renderBulk(filtered);

  if(!filtered.length){
    let msg;
    if(archivedView) msg = `<div class="big">No archived bookmarks${query.trim()? " match “"+esc(query)+"”":""}.</div>`;
    else if(query.trim()) msg = `<div class="big">No bookmarks match “${esc(query)}”.</div><div>Try a different word, topic, or label.</div>`;
    else if(filter==="toread") msg = `<div class="big">Nothing left to read — you're all caught up.</div>`;
    else if(filter==="finished") msg = `<div class="big">Nothing finished yet.</div>`;
    else msg = `<div class="big">Nothing here.</div>`;
    listEl.innerHTML = `<div class="no-results">${msg}</div>`;
    return;
  }
  listEl.innerHTML = filtered.map(b => {
    const col = colorFor(b.domain||b.url);
    const thumb = b.preview
      ? `<div class="thumb" style="background:linear-gradient(135deg,${col},${shade(col)})">${esc(b.preview)}</div>`
      : "";
    const dim = (!archivedView && !b.readLater && filter!=="finished") ? " done" : "";
    const sel = selected.has(b.id);
    const statusBtn = archivedView
      ? `<button class="statusbtn" data-restore="${b.id}">Restore</button>`
      : (b.readLater
          ? `<button class="statusbtn" data-read="${b.id}">Mark as read</button>`
          : `<button class="statusbtn" data-read="${b.id}">Move back to “To read”</button>`);
    const badge = b.readLater ? `<span class="badge">Read later</span>` : `<span class="badge read">Read ✓</span>`;
    return `
    <div class="item${dim}${sel?' selected':''}" id="item-${b.id}">
      <div class="selbox ${sel?'on':''}" data-sel="${b.id}" title="Select">${sel?'✓':''}</div>
      ${thumb}
      <div class="body">
        <div class="titleline">
          <a class="openlink" href="${esc(b.url)}" target="_blank" rel="noopener" title="Open in a new tab">
            <div class="favicon" style="background:${col}">${esc(monogram(b.domain))}</div>
            <p class="title">${hl(b.title)}</p>
          </a>
        </div>
        ${b.desc? `<p class="desc">${hl(b.desc)}</p>`:""}
        <div class="chips">
          ${badge}
          ${(b.tags||[]).map(t=>`<span class="chip" data-label="${esc(t)}" title="Show everything labelled “${esc(t)}”">${hl(t)}</span>`).join("")}
        </div>
        ${statusBtn}
        <p class="url">${hl(b.url)}</p>
        ${b.note? `<p class="note">“${hl(b.note)}”</p>`:""}
      </div>
    </div>`; }).join("");

  listEl.querySelectorAll("[data-sel]").forEach(box=> box.onclick=()=>{
    const id=+box.dataset.sel; if(selected.has(id)) selected.delete(id); else selected.add(id); render();
  });
  listEl.querySelectorAll("[data-read]").forEach(btn=> btn.onclick=()=>{
    const id=+btn.dataset.read; const bk=bookmarks.find(x=>x.id===id);
    if(bk){ bk.readLater=!bk.readLater; save(); render(); }
  });
  listEl.querySelectorAll("[data-restore]").forEach(btn=> btn.onclick=()=>{
    const id=+btn.dataset.restore; const bk=bookmarks.find(x=>x.id===id);
    if(bk){ bk.archived=false; save(); render(); }
  });
  listEl.querySelectorAll("[data-label]").forEach(chip=> chip.onclick=()=>{
    const lab = chip.dataset.label;
    const token = /[\s()"#]/.test(lab) ? `#"${lab}"` : `#${lab}`;
    const cur = searchInput.value.trim();
    let nq;
    if(!cur) nq = token;
    else if(cur.includes(token)) nq = cur;
    else nq = `(${cur}) AND ${token}`;
    searchInput.value = nq; query = nq;
    searchClear.classList.add("show");
    buildQuery(); render();
    window.scrollTo({top:0, behavior:"smooth"});
  });
}

