const collectionsEl = document.getElementById("collections");
function applySearch(q){
  searchInput.value = q; query = q;
  searchClear.classList.toggle("show", !!q.trim());
  buildQuery();
}
function renderCollections(){
  const curQ = query.trim();
  const savedThis = collections.find(c=>c.query.trim()===curQ);
  let html = collections.length ? `<span class="lbl">Saved searches:</span>` : "";
  html += collections.map(c=>`<span class="coll ${c.query.trim()===curQ&&curQ?'active':''}" data-coll="${c.id}">${esc(c.name)}<span class="del" data-delcoll="${c.id}" title="Remove">×</span></span>`).join("");
  if(collSaveMode){
    html += `<span class="lbl">Name:</span><input id="collName" placeholder="e.g. Reading list" /><button class="mini" data-savecoll="1">Save</button><button class="mini ghost" data-cancelcoll="1">Cancel</button>`;
  } else if(curQ && !savedThis){
    html += `<button class="save-coll" data-startsave="1">＋ Save this search</button>`;
  }
  collectionsEl.innerHTML = html;

  collectionsEl.querySelectorAll("[data-coll]").forEach(el=> el.onclick=(e)=>{
    if(e.target.hasAttribute("data-delcoll")) return;
    const c=collections.find(x=>x.id===+el.dataset.coll); if(c){ applySearch(c.query); render(); window.scrollTo({top:0,behavior:"smooth"}); }
  });
  collectionsEl.querySelectorAll("[data-delcoll]").forEach(el=> el.onclick=(e)=>{
    e.stopPropagation(); collections=collections.filter(x=>x.id!==+el.dataset.delcoll); saveCollections(); render();
  });
  const sb=collectionsEl.querySelector("[data-startsave]"); if(sb) sb.onclick=()=>{ collSaveMode=true; render(); const i=document.getElementById("collName"); if(i) i.focus(); };
  const sv=collectionsEl.querySelector("[data-savecoll]"); if(sv) sv.onclick=()=>{
    const name=(document.getElementById("collName").value||"").trim(); if(!name){ return; }
    collections.push({id:Date.now(), name, query:query.trim()}); saveCollections(); collSaveMode=false; render();
  };
  const cc=collectionsEl.querySelector("[data-cancelcoll]"); if(cc) cc.onclick=()=>{ collSaveMode=false; render(); };
}

