// --- tiny, safe formatter for notes: **bold**, *italic*, `code`, - lists, [text](url) ---
function mdRender(md){
  if(!md) return "";
  const e = s => s.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
  const inline = t => {
    t = e(t);
    t = t.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener">$1</a>');
    t = t.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
    t = t.replace(/(^|[^*])\*([^*]+)\*/g,'$1<em>$2</em>');
    t = t.replace(/`([^`]+)`/g,'<code>$1</code>');
    return t;
  };
  const lines = md.split(/\r?\n/); const out=[]; let inList=false;
  for(const ln of lines){
    if(/^\s*-\s+/.test(ln)){ if(!inList){ out.push('<ul>'); inList=true; } out.push('<li>'+inline(ln.replace(/^\s*-\s+/,''))+'</li>'); }
    else { if(inList){ out.push('</ul>'); inList=false; } if(ln.trim()!=='') out.push('<div>'+inline(ln)+'</div>'); }
  }
  if(inList) out.push('</ul>');
  return out.join('');
}

