const fNote = document.getElementById("fNote");
const notePreview = document.getElementById("notePreview");
const notePreviewLabel = document.getElementById("notePreviewLabel");
function updateNotePreview(){
  const v = fNote.value;
  if(v.trim()){ notePreview.innerHTML = mdRender(v); notePreview.style.display="block"; notePreviewLabel.style.display="block"; }
  else { notePreview.style.display="none"; notePreviewLabel.style.display="none"; }
}
fNote.addEventListener("input", updateNotePreview);
function wrapNote(before, after){
  const s=fNote.selectionStart, e=fNote.selectionEnd, v=fNote.value;
  const sel=v.slice(s,e) || "text";
  fNote.value = v.slice(0,s) + before + sel + after + v.slice(e);
  fNote.focus(); fNote.selectionStart = s+before.length; fNote.selectionEnd = s+before.length+sel.length;
  updateNotePreview();
}
document.getElementById("noteToolbar").querySelectorAll("button").forEach(btn=> btn.onclick=()=>{
  const k=btn.dataset.md;
  if(k==="bold") wrapNote("**","**");
  else if(k==="italic") wrapNote("*","*");
  else if(k==="link") wrapNote("[","](https://)");
  else if(k==="list"){
    const s=fNote.selectionStart, v=fNote.value;
    const lineStart = v.lastIndexOf("\n", s-1)+1;
    fNote.value = v.slice(0,lineStart) + "- " + v.slice(lineStart);
    fNote.focus(); updateNotePreview();
  }
});

