// --- import / export (standard Netscape bookmark HTML) ---
const toolsStatus = document.getElementById("toolsStatus");
document.getElementById("exportBtn").onclick = ()=>{
  const rows = bookmarks.map(b=>{
    const dt = b.addedAt ? Math.floor(new Date(b.addedAt).getTime()/1000) : Math.floor(Date.now()/1000);
    const tags = (b.tags||[]).join(",");
    return `    <DT><A HREF="${esc(b.url)}" ADD_DATE="${dt}"${tags?` TAGS="${esc(tags)}"`:""}>${esc(b.title)}</A>`;
  }).join("\n");
  const html = `<!DOCTYPE NETSCAPE-Bookmark-file-1>\n<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">\n<TITLE>Bookmarks</TITLE>\n<H1>Bookmarks</H1>\n<DL><p>\n${rows}\n</DL><p>\n`;
  const blob = new Blob([html], {type:"text/html"}); const url = URL.createObjectURL(blob);
  const a = document.createElement("a"); a.href=url; a.download="bookmarks.html"; document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
  toolsStatus.textContent = `Exported ${bookmarks.length} bookmark${bookmarks.length!==1?"s":""} (titles, labels, and dates).`;
};
const importFile = document.getElementById("importFile");
document.getElementById("importBtn").onclick = ()=> importFile.click();
importFile.onchange = ()=>{
  const file = importFile.files[0]; if(!file) return;
  const reader = new FileReader();
  reader.onload = ()=>{
    const doc = new DOMParser().parseFromString(reader.result, "text/html");
    let added=0, skipped=0;
    [...doc.querySelectorAll("a[href]")].forEach((a,i)=>{
      const url = a.getAttribute("href"); if(!url || !/^https?:/i.test(url)) return;
      if(bookmarks.some(b=>normUrl(b.url)===normUrl(url))){ skipped++; return; }
      const tagAttr = (a.getAttribute("tags")||"").split(",").map(s=>s.trim()).filter(Boolean);
      const folders=[]; let node=a.parentElement;
      while(node){ if(node.tagName==="DL"){ const prev=node.previousElementSibling; if(prev){ const h=prev.tagName==="H3"?prev:prev.querySelector&&prev.querySelector("h3"); if(h) folders.unshift(h.textContent.trim()); } } node=node.parentElement; }
      const tags = [...new Set([...tagAttr, ...folders].filter(Boolean))];
      const addDate = a.getAttribute("add_date");
      const addedAt = addDate ? new Date(parseInt(addDate,10)*1000).toISOString().slice(0,10) : new Date().toISOString().slice(0,10);
      bookmarks.push({ id:Date.now()+i, url, domain:domainOf(url), preview:null, title:(a.textContent||url).trim(), desc:"", note:"", tags, readLater:true, keepCopy:false, copyKind:null, capturedAt:null, copyFailed:false, iaUrl:null, addedAt, archived:false });
      added++;
    });
    save(); render();
    toolsStatus.textContent = `Imported ${added} bookmark${added!==1?"s":""}${skipped?`, skipped ${skipped} already saved`:""}.`;
    importFile.value="";
  };
  reader.readAsText(file);
};

