  const today = new Date().toISOString().slice(0,10);
  if(keepCopy){
    if(readable(domainOf(finalUrl))){
      data.copyKind = finalUrl.toLowerCase().endsWith(".pdf") ? "pdf" : "page";
      data.capturedAt = today; data.copyFailed = false;
    } else {
      data.copyKind = null; data.capturedAt = null; data.copyFailed = true;
    }
  } else { data.copyKind = null; data.capturedAt = null; data.copyFailed = false; }
  data.iaUrl = iaOn ? ("https://web.archive.org/web/"+today.replace(/-/g,"")+"/"+finalUrl) : null;
  if(editingId){
    const i=bookmarks.findIndex(b=>b.id===editingId);
    if(i>=0) bookmarks[i]={...bookmarks[i], ...data};
    save(); render(); overlay.classList.remove("open");
    flash("Updated your saved link.");
    highlight(editingId);
  } else {
    data.id = Date.now();
    data.addedAt = today;
    data.archived = false;
    bookmarks.unshift(data);
    save(); render(); overlay.classList.remove("open");
    urlInput.value="";
  }
};
