:root {
  --bg: #f7f7f5; --card: #ffffff; --ink: #2b2b2b; --muted: #9a9a92;
  --line: #e7e7e2; --accent: #4a6b57; --accent-soft: #e9f0ec; --chip: #eef0ee;
}
* { box-sizing: border-box; }
body { margin: 0; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg); color: var(--ink); line-height: 1.5; }
.wrap { max-width: 760px; margin: 0 auto; padding: 28px 20px 90px; }
header h1 { font-size: 22px; font-weight: 600; margin: 0 0 2px; letter-spacing: -0.01em; }
.tagline { margin: 0 0 12px; color: var(--muted); font-size: 14px; }

.tools-row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin-bottom: 14px; }
.tools-status { font-size: 12.5px; color: var(--muted); }
.ghost-btn { border: 1px solid var(--line); background: #fff; border-radius: 8px; padding: 6px 10px; font-size: 12.5px; color: #6a6a63; cursor: pointer; }
.ghost-btn.active { background: #2b2b2b; color: #fff; border-color: #2b2b2b; }

.display-panel { background: #fff; border: 1px solid var(--line); border-radius: 12px; padding: 12px 16px; margin-bottom: 16px; box-shadow: 0 1px 2px rgba(0,0,0,.03); }
.dp-row { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; padding: 6px 0; }
.dp-label { font-size: 13px; color: #55554e; min-width: 90px; }

.save-bar { background: var(--card); border: 1px solid var(--line); border-radius: 14px; padding: 14px; display: flex; gap: 10px; align-items: center; box-shadow: 0 1px 2px rgba(0,0,0,.03); }
.save-bar input { flex: 1; border: none; outline: none; font-size: 15px; background: transparent; color: var(--ink); }
.btn { border: none; border-radius: 10px; padding: 10px 16px; font-size: 14px; font-weight: 500; cursor: pointer; background: var(--accent); color: #fff; white-space: nowrap; }
.btn.secondary { background: var(--chip); color: var(--ink); }
.url-note { font-size: 12.5px; color: #a84a4a; margin-top: 8px; }

.search-bar { display: flex; align-items: center; gap: 8px; margin-top: 16px; background: #fff; border: 1px solid var(--line); border-radius: 12px; padding: 10px 14px; box-shadow: 0 1px 2px rgba(0,0,0,.03); }
.search-bar svg { width: 16px; height: 16px; color: var(--muted); flex: none; }
.search-bar input { flex: 1; border: none; outline: none; font-size: 14.5px; background: transparent; color: var(--ink); }
.search-clear { border: none; background: transparent; color: var(--muted); cursor: pointer; font-size: 13px; }

.collections { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin-top: 12px; }
.collections .lbl { font-size: 11.5px; color: var(--muted); }
.collections .coll { display: inline-flex; align-items: center; gap: 7px; background: #eef2ef; border: 1px solid #dbe3dd; color: #3f5a4a; border-radius: 999px; padding: 5px 11px; font-size: 12.5px; cursor: pointer; }
.collections .coll.active { background: var(--accent); color: #fff; border-color: var(--accent); }
.collections .coll .del { color: #9aa79f; font-weight: 700; cursor: pointer; }
.collections .coll.active .del { color: #cfe0d6; }
.collections .save-coll { background: transparent; border: 1px dashed #c6cec8; color: #6a6a63; border-radius: 999px; padding: 5px 11px; font-size: 12.5px; cursor: pointer; }
.collections input { border: 1px solid var(--line); border-radius: 8px; padding: 5px 9px; font-size: 13px; }
.collections .mini { border: none; background: var(--accent); color: #fff; border-radius: 8px; padding: 5px 10px; font-size: 12.5px; cursor: pointer; }
.collections .mini.ghost { background: transparent; color: var(--muted); text-decoration: underline; }

.controls-row { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; margin-top: 16px; }
.right-controls { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.seg { display: inline-flex; background: #eceae4; border-radius: 10px; padding: 3px; gap: 2px; }
.seg button { border: none; background: transparent; font-size: 13px; color: #6a6a63; padding: 6px 14px; border-radius: 8px; cursor: pointer; }
.seg button.active { background: #fff; color: #2b2b2b; font-weight: 600; box-shadow: 0 1px 2px rgba(0,0,0,.06); }
.seg .n { color: #a7a7a0; font-weight: 400; margin-left: 4px; font-size: 12px; }
.sel-label { font-size: 12.5px; color: var(--muted); display: inline-flex; align-items: center; gap: 6px; }
.sel-label select { border: 1px solid var(--line); border-radius: 8px; padding: 6px 8px; font-size: 13px; background: #fff; color: var(--ink); font-family: inherit; cursor: pointer; }

.archived-banner { margin-top: 14px; background: #f1eee6; color: #7a6f52; border-radius: 10px; padding: 10px 14px; font-size: 13px; }
.bulkbar { margin-top: 14px; background: #2b2b2b; color: #fff; border-radius: 12px; padding: 10px 14px; display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.bulkbar .count { font-weight: 600; font-size: 13.5px; }
.bulkbar .selall { color: #c9d6cd; font-size: 12.5px; background: transparent; border: none; cursor: pointer; text-decoration: underline; }
.bulkbar .spacer { flex: 1; }
.bulkbar .act { border: none; background: #43433f; color: #fff; font-size: 12.5px; padding: 6px 11px; border-radius: 8px; cursor: pointer; }
.bulkbar .act.danger { background: #7a3a3a; }
.bulkbar input { border: none; border-radius: 8px; padding: 6px 10px; font-size: 13px; min-width: 150px; }
.bulkbar .link { background: transparent; border: none; color: #c9d6cd; cursor: pointer; font-size: 12.5px; text-decoration: underline; }
.bulkbar .sugwrap { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.bulkbar .sug-label { color: #a7b3ab; font-size: 11.5px; }
.bulkbar .sug { background: #43433f; color: #e7e7e2; border: 1px dashed #6a6a63; border-radius: 999px; padding: 4px 10px; font-size: 12px; cursor: pointer; }

.result-count { font-size: 12px; color: var(--muted); margin: 14px 2px 0; }

.list { margin-top: 10px; display: flex; flex-direction: column; gap: 12px; }
.item { position: relative; background: var(--card); border: 1px solid var(--line); border-radius: 14px; padding: 14px 16px; box-shadow: 0 1px 2px rgba(0,0,0,.03); display: flex; gap: 14px; align-items: flex-start; }
.item.done { opacity: .72; }
.item.selected { border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent-soft); }
.item.flash-hit { animation: hit 1.6s ease; }
@keyframes hit { 0% { box-shadow: 0 0 0 3px var(--accent); } 100% { box-shadow: 0 1px 2px rgba(0,0,0,.03); } }
.selbox { width: 20px; min-width: 20px; height: 20px; border-radius: 6px; border: 2px solid #cdd4cf; cursor: pointer; margin-top: 2px; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 12px; }
.selbox.on { background: var(--accent); border-color: var(--accent); }
.thumb { width: 82px; min-width: 82px; height: 60px; border-radius: 8px; overflow: hidden; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 12px; font-weight: 600; text-align: center; object-fit: cover; }
img.thumb { object-fit: cover; }
.body { flex: 1; min-width: 0; }
.titleline { display: flex; align-items: center; gap: 8px; }
.openlink { display: flex; align-items: center; gap: 8px; text-decoration: none; color: inherit; min-width: 0; }
.favicon { width: 18px; height: 18px; min-width: 18px; border-radius: 5px; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 10px; font-weight: 700; overflow: hidden; }
.favicon img { width: 18px; height: 18px; }
.title { font-size: 15.5px; font-weight: 600; margin: 0; overflow-wrap: anywhere; }
.openlink:hover .title { text-decoration: underline; color: #3a5a47; }
.desc { font-size: 13.5px; color: #55554e; margin: 6px 0 8px; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.chips { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.chip { background: var(--chip); color: #4a4a44; font-size: 12px; padding: 3px 10px; border-radius: 999px; cursor: pointer; }
.chip:hover { background: #e2e7e3; color: #2b2b2b; }
.badge { font-size: 11px; padding: 2px 9px; border-radius: 999px; background: #f2ede0; color: #8a7a4a; font-weight: 600; }
.badge.read { background: var(--accent-soft); color: #3f6b53; }
.statusbtn { margin-top: 10px; font-size: 12.5px; font-weight: 600; color: var(--accent); background: var(--accent-soft); border: none; border-radius: 999px; padding: 5px 12px; cursor: pointer; }
.url { font-size: 11.5px; color: var(--muted); word-break: break-all; margin: 8px 0 0; }
.note-wrap { margin-top: 8px; }
.note { font-size: 12.5px; color: #6a6a63; background: #fbfbf9; border-left: 3px solid var(--accent-soft); padding: 6px 10px; border-radius: 4px; }
.note div { margin: 0; } .note ul, .note ol { margin: 2px 0; padding-left: 20px; }
.note h3 { font-size: 13.5px; margin: 4px 0 2px; } .note h4 { font-size: 12.5px; margin: 4px 0 2px; color: #55554e; }
.note strong { color: #3f3f3a; } .note code { background: #eceae4; padding: 0 4px; border-radius: 3px; } .note a { color: var(--accent); }
.note.collapsed { max-height: 4.6em; overflow: hidden; -webkit-mask-image: linear-gradient(to bottom, #000 70%, transparent); mask-image: linear-gradient(to bottom, #000 70%, transparent); }
.note-toggle { border: none; background: transparent; color: var(--accent); font-size: 12px; cursor: pointer; margin-top: 2px; }
.copy-row { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 8px; }
.copy-link { display: inline-flex; align-items: center; gap: 4px; font-size: 12px; color: var(--accent); background: var(--accent-soft); border: none; border-radius: 999px; padding: 3px 10px; cursor: pointer; text-decoration: none; }
.copy-link.ghost { background: #f2f2ee; color: #6a6a63; }
.copy-link.fail { background: #f6e7e3; color: #a84a4a; }

.empty, .no-results { text-align: center; color: var(--muted); padding: 56px 20px; }
.empty .big, .no-results .big { font-size: 15px; color: #6a6a63; margin-bottom: 4px; }
.show-more { display: block; margin: 16px auto 0; border: 1px solid var(--line); background: #fff; border-radius: 10px; padding: 9px 18px; font-size: 13.5px; color: var(--accent); cursor: pointer; }

.overlay { position: fixed; inset: 0; background: rgba(30,30,28,.35); display: flex; align-items: flex-start; justify-content: center; padding: 40px 16px; overflow: auto; }
.overlay[hidden] { display: none; }
.modal { background: var(--card); border-radius: 16px; width: 100%; max-width: 500px; padding: 22px; box-shadow: 0 20px 60px rgba(0,0,0,.2); }
.modal h2 { font-size: 17px; margin: 0 0 4px; }
.modal .hint { font-size: 13px; color: var(--muted); margin: 0 0 16px; }
.preview-row { display: flex; gap: 12px; align-items: center; margin-bottom: 16px; }
#mThumb { width: 96px; min-width: 96px; height: 64px; border-radius: 8px; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 11px; font-weight: 600; text-align: center; overflow: hidden; }
#mThumb img { width: 100%; height: 100%; object-fit: cover; }
.mfav { width: 26px; height: 26px; border-radius: 6px; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 12px; font-weight: 700; overflow: hidden; }
.mfav img { width: 26px; height: 26px; }
.preview-cap { font-size: 11.5px; color: var(--accent); }
.field { margin-bottom: 14px; }
.field label { display: block; font-size: 12.5px; color: var(--muted); margin-bottom: 5px; }
.field input, .field textarea { width: 100%; border: 1px solid var(--line); border-radius: 9px; padding: 9px 11px; font-size: 14px; font-family: inherit; outline: none; background: #fcfcfa; color: var(--ink); }
.field textarea { resize: vertical; min-height: 54px; }
.field .auto { font-size: 11.5px; color: var(--accent); margin-top: 4px; }
.field-err { font-size: 12px; color: #a84a4a; margin-top: 5px; }
.suggest { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.suggest .s-label { font-size: 11.5px; color: var(--muted); width: 100%; }
.suggest .chip { cursor: pointer; border: 1px dashed #cdd4cf; background: #f6f8f6; }
.toggle-row { display: flex; align-items: center; gap: 10px; background: #faf9f5; border: 1px solid var(--line); border-radius: 10px; padding: 10px 12px; margin-bottom: 12px; }
.switch { position: relative; width: 42px; min-width: 42px; height: 24px; background: #cfcfc7; border: none; border-radius: 999px; cursor: pointer; padding: 0; transition: .2s; }
.switch.on { background: var(--accent); }
.switch .knob { position: absolute; top: 2px; left: 2px; width: 20px; height: 20px; background: #fff; border-radius: 50%; transition: .2s; }
.switch.on .knob { left: 20px; }
.t-text { font-size: 13.5px; } .t-sub { font-size: 11.5px; color: var(--muted); } .ia-note { color: #a06a2a; font-weight: 600; }
.note-toolbar { display: flex; gap: 6px; margin-bottom: 6px; }
.note-toolbar button { border: 1px solid var(--line); background: #fff; border-radius: 6px; padding: 3px 9px; font-size: 12.5px; cursor: pointer; color: #55554e; }
.note-preview-label { font-size: 11px; color: var(--muted); margin-top: 8px; }
.note-preview { font-size: 13px; color: #55554e; background: #fbfbf9; border: 1px solid var(--line); border-radius: 8px; padding: 8px 10px; margin-top: 4px; }
.note-preview ul, .note-preview ol { margin: 4px 0; padding-left: 18px; } .note-preview code { background: #eceae4; padding: 0 4px; border-radius: 3px; }
.actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 8px; }

.toast { position: fixed; left: 50%; bottom: 26px; transform: translateX(-50%); background: #2b2b2b; color: #fff; padding: 10px 16px; border-radius: 10px; font-size: 13px; opacity: 0; transition: .2s; pointer-events: none; max-width: 90%; }
.toast.show { opacity: 1; }

/* text-size preference (SCN-022) */
body.fs-small .title { font-size: 14px; } body.fs-small .desc { font-size: 12.5px; } body.fs-small .url { font-size: 11px; } body.fs-small .note { font-size: 11.5px; }
body.fs-large .title { font-size: 18px; } body.fs-large .desc { font-size: 15px; } body.fs-large .url { font-size: 12.5px; } body.fs-large .note { font-size: 14px; }

@media (max-width: 520px) {
  .thumb { width: 64px; min-width: 64px; height: 48px; }
  .controls-row { flex-direction: column; align-items: stretch; }
}

