body.fs-small .title { font-size: 14px; } body.fs-small .desc { font-size: 12.5px; } body.fs-small .url { font-size: 11px; } body.fs-small .note { font-size: 11.5px; }
body.fs-large .title { font-size: 18px; } body.fs-large .desc { font-size: 15px; } body.fs-large .url { font-size: 12.5px; } body.fs-large .note { font-size: 14px; }

@media (max-width: 520px) {
  .thumb { width: 64px; min-width: 64px; height: 48px; }
  .controls-row { flex-direction: column; align-items: stretch; }
}

