.field input, .field textarea { width: 100%; border: 1px solid var(--line); border-radius: 9px; padding: 9px 11px; font-size: 14px; font-family: inherit; outline: none; background: #fcfcfa; color: var(--ink); }
.field textarea { resize: vertical; min-height: 54px; }
.field .auto { font-size: 11.5px; color: var(--accent); margin-top: 4px; }
.field-err { font-size: 12px; color: #a84a4a; margin-top: 5px; }
.suggest { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.suggest .s-label { font-size: 11.5px; color: var(--muted); width: 100%; }
.suggest .chip { cursor: pointer; border: 1px dashed #cdd4cf; background: #f6f8f6; }
.toggle-row { display: flex; align-items: center; gap: 10px; background: #faf9f5; border: 1px solid var(--line); border-radius: 10px; padding: 10px 12px; margin-bottom: 12px; }
.switch { position: relative; width: 42px; min-width: 42px; height: 24px; background: #cfcfc7; border: none; border-radius: 999px; cursor: pointer; padding: 0; transition: .2s; }
.switch.on { background: var(--accent); }
.switch .knob { position: absolute; top: 2px; left: 2px; width: 20px; height: 20px; background: #fff; border-radius: 50%; transition: .2s; }
.switch.on .knob { left: 20px; }
.t-text { font-size: 13.5px; } .t-sub { font-size: 11.5px; color: var(--muted); } .ia-note { color: #a06a2a; font-weight: 600; }
.note-toolbar { display: flex; gap: 6px; margin-bottom: 6px; }
.note-toolbar button { border: 1px solid var(--line); background: #fff; border-radius: 6px; padding: 3px 9px; font-size: 12.5px; cursor: pointer; color: #55554e; }
.note-preview-label { font-size: 11px; color: var(--muted); margin-top: 8px; }
.note-preview { font-size: 13px; color: #55554e; background: #fbfbf9; border: 1px solid var(--line); border-radius: 8px; padding: 8px 10px; margin-top: 4px; }
.note-preview ul, .note-preview ol { margin: 4px 0; padding-left: 18px; } .note-preview code { background: #eceae4; padding: 0 4px; border-radius: 3px; }
.actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 8px; }

.toast { position: fixed; left: 50%; bottom: 26px; transform: translateX(-50%); background: #2b2b2b; color: #fff; padding: 10px 16px; border-radius: 10px; font-size: 13px; opacity: 0; transition: .2s; pointer-events: none; max-width: 90%; }
.toast.show { opacity: 1; }

/* text-size preference (SCN-022) */
body.fs-small .title { font-size: 14px; } body.fs-small .desc { font-size: 12.5px; } body.fs-small .url { font-size: 11px; } body.fs-small .note { font-size: 11.5px; }
body.fs-large .title { font-size: 18px; } body.fs-large .desc { font-size: 15px; } body.fs-large .url { font-size: 12.5px; } body.fs-large .note { font-size: 14px; }

@media (max-width: 520px) {
  .thumb { width: 64px; min-width: 64px; height: 48px; }
  .controls-row { flex-direction: column; align-items: stretch; }
}

